style.css:
@-moz-document domain("html-leerplatform.vercel.app") {
/* Basis achtergrond en tekstkleur aanpassen */
    html, body, main, appointment, #__next, .min-h-screen {
        background-color: #ffffff !important;
        color: #1a1a1a !important;
    }

    /* Alle containers, kaarten en navigatiebalken wit maken */
    div, section, nav, header, aside, article {
        background-color: #ffffff !important;
        color: #1a1a1a !important;
        border-color: #e5e7eb !important; /* Lichte randen */
    }

    /* Teksten en titels goed leesbaar maken (donkergrijs/zwart) */
    p, span, h1, h2, h3, h4, h5, h6, li, a, b, strong {
        color: #1a1a1a !important;
    }

    /* Links een duidelijke blauwe kleur geven */
    a {
        color: #2563eb !important;
        text-decoration: underline !important;
    }

    /* Knoppen en invoervelden stylen zodat ze niet wegvallen */
    button, input, textarea, select {
        background-color: #f3f4f6 !important;
        color: #1a1a1a !important;
        border: 1px solid #d1d5db !important;
    }

    /* Specifieke codeblokken (vaak gebruikt op een HTML platform) herkenbaar houden */
    pre, code {
        background-color: #f8fafc !important;
        color: #0f172a !important;
        border: 1px solid #e2e8f0 !important;
    }
}
